import type { Metadata, Viewport } from 'next';
import { DetailGamePageClient } from './GamePageClient';

export const viewport: Viewport = { themeColor: '#F5FAFB' };

type Params = {
  params: Promise<{ params: string[] }>;
};

export async function generateMetadata({ params }: Params): Promise<Metadata> {
  const { params: dynamicParams } = await params;
  const [title] = dynamicParams; // Extraction correcte des paramètres depuis `params.params`
  return {
    title: title.replaceAll('-', ' '),
    description: 'Des vrais jeux vous attendent',
  };
}

export default async function GamePage({ params }: Params) {
  const { params: dynamicParams } = await params; // Assure-toi que tu vois bien la structure des paramètres
  const [gameTitle, id] = dynamicParams; // Extraction correcte des paramètres depuis `params.params`

  // Vérifie si `id` et `gameTitle` sont définis
  if (!id || !gameTitle) {
    return <div>Aucun jeu trouvé</div>;
  }

  return <DetailGamePageClient id={id} />;
}
